sys_script_email.script:
(function runMailScript(current, template, email, email_action, event) {

    if (current.getTableName() == 'sysapproval_approver') {
        var msrGr = new GlideRecord('x_snp_manager_su_0_manager_support_request');
        if (msrGr.get(current.getValue('sysapproval')))
            printDetails(msrGr);
    } else {
        printDetails(current);
    }

    function printDetails(msrGr) {
        var rows = [
            ['Request', msrGr.getValue('number') + ' - ' + msrGr.getValue('short_description')],
            ['Requester', msrGr.opened_for.getDisplayValue()],
            ['Employee', msrGr.subject_person.getDisplayValue()],
            ['Request type', msrGr.request_type.getDisplayValue()],
            ['Due date', msrGr.due_date.getDisplayValue()],
            ['Days to due', msrGr.getValue('days_to_due')],
            ['Approver', msrGr.opened_for.manager.getDisplayValue()],
            ['HR team', msrGr.assignment_group.getDisplayValue()]
        ];
        template.print('<table cellpadding="4" style="border-collapse:collapse">');
        rows.forEach(function(r) {
            template.print('<tr><td style="color:#555"><b>' + r[0] + '</b></td><td>' + escapeHtml(r[1]) + '</td></tr>');
        });
        template.print('</table>');
    }

    // User-entered text must not inject HTML into the email
    function escapeHtml(text) {
        return String(text || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
    }

})(current, template, email, email_action, event);
